import re, json

# Load the JSON and look for the TF-G chart data
with open('/app/resources/treasury_bulletin_1992_03.json', 'r') as f:
    data = json.load(f)

# The data is in elements - let's find the page 148 content (TF-G chart)
def find_elements_by_page(obj, target_page=None, path=""):
    results = []
    if isinstance(obj, dict):
        if 'page_id' in obj and obj.get('page_id') == target_page:
            results.append((path, obj))
        for k, v in obj.items():
            results.extend(find_elements_by_page(v, target_page, path + "." + k if path else k))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_elements_by_page(item, target_page, f"{path}[{i}]"))
    return results

# Page 148 is where TF-G chart should be - but let's check elements for highway
def find_all_elements(obj, path=""):
    results = []
    if isinstance(obj, dict):
        if obj.get('type') in ['text', 'table', 'figure']:
            content = obj.get('content', '')
            if content and 'highway' in str(content).lower():
                results.append((path, obj.get('type'), str(content)[:200]))
        for k, v in obj.items():
            results.extend(find_all_elements(v, path + "." + k if path else k))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(find_all_elements(item, f"{path}[{i}]"))
    return results

results = find_all_elements(data)
for r in results[:30]:
    print(f"{r[1]}: {r[2]}")
