import re, json

# Load the JSON and look for the TF-G chart (page 148 in original PDF = element with fiscal years 1986-91)
with open('/app/resources/treasury_bulletin_1992_03.json', 'r') as f:
    data = json.load(f)

# Search for exact phrase "highway trust funds"
def search_text(obj, search_term, path="", depth=0):
    results = []
    if depth > 10:
        return results
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, str) and search_term.lower() in v.lower():
                results.append((path + "." + k if path else k, v[:500]))
            results.extend(search_text(v, search_term, path + "." + k if path else k, depth+1))
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            results.extend(search_text(item, search_term, f"{path}[{i}]", depth+1))
    return results

# Search for chart data showing receipts and outlays
results = search_text(data, "TF-G")
for r in results:
    print(f"{r[0]}")
    print(f"Content: {r[1]}")
    print("---")
EOF
